describe('Inline Table Row Editing', () => {
  beforeEach(() => {
    cy.visit('/table-view');
  });

  it('should allow inline editing of a table row without opening a modal', () => {
    // Verify table is visible and contains data
    cy.get('[data-testid="data-table"]').should('be.visible');
    cy.get('[data-testid="table-row"]').first().should('be.visible');
    cy.get('[data-testid="table-cell"]').first().should('contain', 'John Doe');

    // Click edit button to enter inline editing mode
    cy.get('[data-testid="edit-button"]').first().click();
    cy.get('[data-testid="table-cell"]').first().should('have.attr', 'contenteditable', 'true');
    cy.get('[data-testid="table-cell"]').first().should('contain', 'John Doe');

    // Type new value into the editable cell
    cy.get('[data-testid="table-cell"]').first().type('Jane Doe');
    cy.get('[data-testid="table-cell"]').first().should('have.value', 'Jane Doe');

    // Click save button to commit changes
    cy.get('[data-testid="save-button"]').first().click();
    cy.get('[data-testid="table-cell"]').first().should('not.have.attr', 'contenteditable', 'true');
    cy.get('[data-testid="table-cell"]').first().should('contain', 'Jane Doe');

    // Verify success message appears
    cy.get('[data-testid="success-message"]').should('be.visible');
    cy.get('[data-testid="success-message"]').should('contain', 'Row updated successfully');
  });

  it('should handle empty or invalid input during inline editing and prevent save', () => {
    // Verify table is visible
    cy.get('[data-testid="data-table"]').should('be.visible');

    // Click edit button
    cy.get('[data-testid="edit-button"]').first().click();
    cy.get('[data-testid="table-cell"]').first().should('have.attr', 'contenteditable', 'true');

    // Clear the cell content
    cy.get('[data-testid="table-cell"]').first().clear();
    cy.get('[data-testid="table-cell"]').first().should('have.value', '');

    // Attempt to save with empty input
    cy.get('[data-testid="save-button"]').first().click();

    // Verify error message appears instead of success
    cy.get('[data-testid="error-message"]').should('be.visible');
    cy.get('[data-testid="error-message"]').should('contain', 'Input cannot be empty');

    // Verify cell is still in edit mode
    cy.get('[data-testid="table-cell"]').first().should('have.attr', 'contenteditable', 'true');

    // Type valid input and save successfully
    cy.get('[data-testid="table-cell"]').first().type('Valid Name');
    cy.get('[data-testid="save-button"]').first().click();
    cy.get('[data-testid="table-cell"]').first().should('not.have.attr', 'contenteditable', 'true');
    cy.get('[data-testid="success-message"]').should('be.visible');
  });
});
